UPDATE tools SET choose_if = $x$["🗂️ Ihr Team führt Dokumente, Wikis und Projekte bereits in Notion", "💳 Sie nutzen bereits den Business-Plan (20 US-Dollar/Sitzplatz/Monat) oder sind bereit, dafür vollständige KI zu wechseln", "🔄 Sie möchten zwischen Modellen verschiedener KI-Anbieter wechseln, ohne Ihre Notizen zu verlassen", "🔍 Sie benötigen arbeitsbereichsweite Suche, Meeting-Notizen oder Recherche in einem einzigen Tool", "🤖 Sie möchten Custom Agents gegen Ihre eigenen Inhalte erstellen und überprüfen"]$x$::jsonb
