UPDATE tools SET faq = $x$[{"q": "Was ist Notion AI?", "a": "Notion AI ist ein KI-Assistent, der direkt in Notion integriert ist. Er kann schreiben, zusammenfassen, übersetzen und Fragen unter Verwendung der Inhalte Ihres Arbeitsbereichs als Kontext beantworten."}, {"q": "Wie viel kostet Notion AI?", "a": "Notion AI wird nicht als separates Zusatzpaket verkauft. Die Pläne Free und Plus enthalten nur eine begrenzte Testversion von Notion AI. Vollständige, dauerhafte KI ist im Business-Plan (20 US-Dollar pro Sitzplatz und Monat) sowie in Enterprise enthalten, das individuell bepreist wird; bei jährlicher Abrechnung lassen sich bis zu 20 % sparen."}, {"q": "Was sind Skills in Notion 3.7?", "a": "Notion 3.7 (September 2026) führte Agenten-Skills und eine Skills-Bibliothek ein, mit der Möglichkeit, Skills an externe Tools wie Claude Code, Codex, Cursor, Gemini und Grok zu exportieren, sowie Custom Agents, die Sub-Agenten aufrufen können."}, {"q": "Wie funktionieren die Credits für Custom Agents?", "a": "Business- und Enterprise-Sitzplätze enthalten monatlich 1.500 Standard-Credits und 500 Select-Credits; Custom Agents greifen auf die Select-Credits zurück. Arbeitsbereichs-Administratoren können zusätzliche Credits für den Arbeitsbereich kaufen, die laut Notions Preisseite 10 US-Dollar pro 1.000 monatlichen Credits kosten."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'de';

