UPDATE tools SET faq = $x$[{"q": "Що таке Notion AI?", "a": "Notion AI — це AI-асистент, вбудований безпосередньо в Notion. Він може писати, узагальнювати, перекладати та відповідати на запитання, використовуючи контент вашого робочого простору як контекст."}, {"q": "Скільки коштує Notion AI?", "a": "Notion AI не є окремим доповненням. Плани Free і Plus включають лише обмежену пробну версію Notion AI. Повний, постійний AI включений у план Business ($20 за місце на місяць) та в Enterprise, який має індивідуальне ціноутворення; річна оплата може заощадити до 20%."}, {"q": "Що таке Skills у Notion 3.7?", "a": "Notion 3.7 (вересень 2026) запровадив Skills для агентів і бібліотеку skills, з можливістю експортувати Skills у зовнішні інструменти, такі як Claude Code, Codex, Cursor, Gemini і Grok, а також Custom Agents, здатні викликати підагентів."}, {"q": "Як працюють кредити Custom Agent?", "a": "Місця Business і Enterprise включають 1500 Standard-кредитів і 500 Select-кредитів на місяць; Custom Agents використовують Select-кредити. Адміністратори робочого простору можуть купувати додаткові кредити для робочого простору, які сторінка цін Notion вказує як $10 за 1000 місячних кредитів."}]$x$::jsonb
