UPDATE tools SET faq = $x$[{"q": "Ist Canva AI kostenlos?", "a": "Canva bietet einen kostenlosen Plan mit einem begrenzten KI-Kontingent, das sich auf die Standard-, Premium- und Ultra-KI-Werkzeuge verteilt. Die kostenpflichtigen Pläne Pro (120 US-Dollar/Jahr für eine Person) und Business (210 US-Dollar/Jahr pro Person) schalten weitere KI-Werkzeuge frei, etwa die Dream-Lab-Bildgenerierung (angetrieben von Canva Craft) und Magic Write, plus ein optionales monatliches AI-Pass-Zusatzpaket für zusätzliche KI-Nutzung; Enterprise wird individuell bepreist. Die Preise werden regional angepasst."}, {"q": "Welche KI-Funktionen bietet Figma?", "a": "Figma AI (eingeführt 2024) umfasst KI-generierte Ebenen und Designs aus Textvorgaben, KI-Umbenennung von Ebenen, Erstellung erster Entwürfe sowie Prototyp-Generierung. Es ist in Figma integriert und für alle Nutzer kostenpflichtiger Pläne verfügbar."}, {"q": "Kann Canva Figma ersetzen?", "a": "Nein. Canva und Figma dienen unterschiedlichen Zwecken. Canva ist für die Erstellung von Marketinginhalten und Präsentationen gedacht. Figma dient der Gestaltung von UI/UX-Oberflächen und Produktprototypen. Designer nutzen Figma, Content-Ersteller nutzen Canva."}, {"q": "Was eignet sich besser für Anfänger — Canva oder Figma?", "a": "Canva ist für Anfänger deutlich einfacher — es ist für Nicht-Designer mit Drag-and-Drop-Einfachheit konzipiert. Figma hat eine steilere Lernkurve und ist für professionelle Designer ausgelegt. Für schnelle Grafiken sollte man mit Canva beginnen."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'de';

