UPDATE tools SET faq = $x$[{"q": "האם Canva AI חינמי?", "a": "ל-Canva יש תוכנית Free עם מכסת AI מוגבלת המשותפת לכלי Standard, Premium ו-Ultra AI שלה. תוכניות בתשלום Pro (120$ לשנה למשתמש אחד) ו-Business (210$ לשנה למשתמש) פותחות כלי AI נוספים כגון יצירת תמונות ב-Dream Lab (המופעל על ידי Canva Craft) ו-Magic Write, בתוספת תוספת חודשית אופציונלית של AI Pass לשימוש AI נוסף; Enterprise במחיר מותאם אישית. התמחור מותאם לפי אזור."}, {"q": "אילו תכונות AI יש ל-Figma?", "a": "Figma AI (הושק ב-2024) כולל שכבות ועיצובים שנוצרים על ידי AI מהנחיות טקסט, שינוי שם אוטומטי לשכבות, יצירת טיוטה ראשונה, ויצירת פרוטוטייפים. הוא מובנה בתוך Figma וזמין לכל משתמשי התוכניות בתשלום."}, {"q": "האם Canva יכול להחליף את Figma?", "a": "לא. Canva ו-Figma משרתים מטרות שונות. Canva מיועד ליצירת תוכן שיווקי ומצגות. Figma מיועד לעיצוב ממשקי UI/UX ופרוטוטייפים של מוצרים. מעצבים משתמשים ב-Figma; יוצרי תוכן משתמשים ב-Canva."}, {"q": "מה עדיף למתחילים — Canva או Figma?", "a": "Canva קל משמעותית למתחילים — הוא מיועד ללא-מעצבים עם פשטות של גרירה ושחרור. ל-Figma יש עקומת למידה תלולה יותר והוא מיועד למעצבים מקצועיים. לגרפיקה מהירה, התחילו עם Canva."}]$x$::jsonb
