UPDATE tools SET faq = $x$[{"q": "O Canva AI é gratuito?", "a": "A Canva tem um plano Free com uma cota limitada de IA compartilhada entre as ferramentas de IA Standard, Premium e Ultra. Os planos pagos Pro (US$ 120/ano por pessoa) e Business (US$ 210/ano por pessoa) desbloqueiam mais ferramentas de IA, como a geração de imagens do Dream Lab (alimentado pelo Canva Craft) e o Magic Write, além de um complemento opcional mensal AI Pass para uso extra de IA; o Enterprise tem preço personalizado. Os preços são localizados por região."}, {"q": "Quais recursos de IA o Figma tem?", "a": "O Figma AI (lançado em 2024) inclui camadas e designs gerados por IA a partir de prompts de texto, renomeação automática de camadas por IA, geração de primeira versão e geração de protótipos. Ele é integrado ao Figma e está disponível para todos os usuários de planos pagos."}, {"q": "O Canva pode substituir o Figma?", "a": "Não. Canva e Figma atendem a propósitos diferentes. O Canva serve para criar conteúdo de marketing e apresentações. O Figma serve para projetar interfaces de UI/UX e protótipos de produtos. Designers usam o Figma; criadores de conteúdo usam o Canva."}, {"q": "Qual é melhor para iniciantes — Canva ou Figma?", "a": "O Canva é significativamente mais fácil para iniciantes — foi projetado para não-designers, com simplicidade de arrastar e soltar. O Figma tem uma curva de aprendizado mais acentuada e é voltado para designers profissionais. Para criar gráficos rapidamente, comece pelo Canva."}]$x$::jsonb
