UPDATE tools SET faq = $x$[{"a": "ElevenLabs produziert qualitativ hochwertigere, natürlicher klingende Stimmen und bietet überlegenes Voice-Cloning. Murf eignet sich besser für E-Learning- und Präsentations-Voiceovers dank integrierter Videosynchronisation und Team-Funktionen. Wählen Sie ElevenLabs für Qualität, Murf für E-Learning-Workflows.", "q": "Ist ElevenLabs besser als Murf?"}, {"a": "Ja. ElevenLabs kann mit etwa 10 Sekunden sauberem Audiomaterial einen Instant Voice Clone erstellen, verfügbar im Starter-Plan (6 $/Monat bzw. 5 $/Monat bei jährlicher Abrechnung). Professional Voice Clone, für qualitativ hochwertigere Ergebnisse, erfordert den Creator-Plan (22 $/Monat bzw. 18,33 $/Monat bei jährlicher Abrechnung).", "q": "Kann ElevenLabs meine Stimme klonen?"}, {"a": "Die aktuellen Modelle von ElevenLabs — Eleven v4, Eleven v4 Turbo und die neueren Eleven Realtime Sprachagentenmodelle — unterstützen mehr als 90 Sprachen. Die Sprachqualität variiert je nach Sprache — Englisch und die großen europäischen Sprachen liefern die natürlichste Ausgabe.", "q": "Welche Sprachen unterstützt ElevenLabs?"}]$x$::jsonb
