UPDATE tools SET faq = $x$[{"a": "ElevenLabs создаёт более качественные, более естественно звучащие голоса и предлагает более совершенное клонирование голоса. Murf лучше подходит для озвучки электронного обучения и презентаций благодаря встроенной синхронизации с видео и командным функциям. Выбирайте ElevenLabs ради качества; Murf — для рабочих процессов в сфере e-learning.", "q": "Лучше ли ElevenLabs, чем Murf?"}, {"a": "Да. ElevenLabs может создать Instant Voice Clone (мгновенный клон голоса) примерно по 10 секундам чистого аудио, эта функция доступна на тарифе Starter ($6/месяц, или $5/месяц при годовой оплате). Professional Voice Clone, для более высокого качества результата, требует тарифа Creator ($22/месяц, или $18,33/месяц при годовой оплате).", "q": "Может ли ElevenLabs клонировать мой голос?"}, {"a": "Текущие модели ElevenLabs — Eleven v4, Eleven v4 Turbo и более новые голосовые модели для агентов Eleven Realtime — поддерживают более 90 языков. Качество голоса зависит от языка — английский и основные европейские языки дают наиболее естественный результат.", "q": "Какие языки поддерживает ElevenLabs?"}]$x$::jsonb
