UPDATE tools SET faq = $x$[{"q": "¿Qué es Zapier AI?", "a": "Zapier AI es la capa de IA dentro de Zapier que permite crear flujos de trabajo automatizados usando lenguaje natural. Describes lo que quieres automatizar, y Zapier AI genera el flujo de trabajo conectando más de 9.000 aplicaciones."}, {"q": "¿Cuánto cuesta Zapier?", "a": "Zapier tiene un plan gratuito con 100 tareas/mes y Zaps de dos pasos ilimitados. Professional comienza en 19,99 $/mes con facturación anual (29,99 $/mes con facturación mensual) con 750 tareas. Team comienza en 69 $/mes con facturación anual (103,50 $/mes con facturación mensual) para 25 usuarios. Enterprise tiene precio personalizado."}, {"q": "¿Qué puede automatizar Zapier AI?", "a": "Zapier AI puede automatizar respuestas de correo electrónico, actualizaciones de CRM, publicaciones en redes sociales, entrada de datos, enrutamiento de leads y cualquier tarea repetitiva en más de 9.000 aplicaciones conectadas, activada por eventos o según un horario."}, {"q": "¿En qué se diferencia Zapier AI de n8n?", "a": "Zapier es un SaaS sin código con la biblioteca de integración de aplicaciones más grande. n8n es de código abierto y autoalojable, y ofrece más flexibilidad y menor costo a escala para usuarios técnicos."}]$x$::jsonb
