UPDATE tools SET faq = $x$[{"q": "O que é o Zapier AI?", "a": "Zapier AI é a camada de IA dentro do Zapier que permite criar fluxos de trabalho automatizados usando linguagem natural. Você descreve o que deseja automatizar, e o Zapier AI gera o fluxo de trabalho conectando mais de 9.000 aplicativos."}, {"q": "Quanto custa o Zapier?", "a": "O Zapier tem um plano gratuito com 100 tarefas/mês e Zaps de duas etapas ilimitados. O Professional começa em US$ 19,99/mês cobrados anualmente (US$ 29,99/mês cobrados mensalmente) com 750 tarefas. O Team começa em US$ 69/mês cobrados anualmente (US$ 103,50/mês cobrados mensalmente) para 25 usuários. O Enterprise tem preço personalizado."}, {"q": "O que o Zapier AI pode automatizar?", "a": "O Zapier AI pode automatizar respostas de e-mail, atualizações de CRM, postagens em redes sociais, entrada de dados, roteamento de leads e qualquer tarefa repetitiva entre mais de 9.000 aplicativos conectados — acionados por eventos ou em uma programação."}, {"q": "Qual a diferença entre o Zapier AI e o n8n?", "a": "O Zapier é um SaaS sem código com a maior biblioteca de integração de aplicativos. O n8n é de código aberto e pode ser auto-hospedado, oferecendo mais flexibilidade e custo menor em escala para usuários técnicos."}]$x$::jsonb
