UPDATE tools SET faq = $x$[{"a": "Windsurf heißt jetzt Devin Desktop, ein KI-nativer Code-Editor von Cognition, der sich aus Codeium/Windsurf entwickelt hat. Seine Kernfunktion ist eine Agenten-Kommandozentrale mit autonomen Coding-Agenten wie Devin Local, Devin Cloud, Codex, Claude Agent, OpenCode und Cascade, die den Kontext deiner Codebasis kennen.", "q": "Was ist Windsurf?"}, {"a": "Devin Desktop (ehemals Windsurf) bietet einen kostenlosen Tarif mit einem leichten Agenten-Kontingent, eingeschränktem Modellzugang sowie unbegrenzten Tab-Vervollständigungen und Inline-Bearbeitungen. Pro kostet 20 $ pro Monat für mehr Kontingent und vollständigen Modellzugang.", "q": "Ist Windsurf kostenlos?"}, {"a": "Beide sind starke KI-IDEs, und der Abstand zwischen ihnen wird kleiner. Cursor bietet mehr Funktionen, eine größere Community und mehr Modelloptionen. Der Multi-Agenten-Aufbau und der kostenlose Tarif von Devin Desktop sind Vorteile. Viele Entwickler probieren beide aus; die beste Wahl hängt oft von der persönlichen Arbeitsweise ab.", "q": "Ist Windsurf besser als Cursor?"}, {"a": "Cascade ist einer von mehreren auswählbaren Coding-Agenten in Devin Desktop, neben Devin Local, Codex, Claude Agent und OpenCode. Er war der ursprüngliche Windsurf-Agent und kann weiterhin mehrstufige Änderungen über ein ganzes Projekt hinweg planen und ausführen.", "q": "Was ist Cascade in Windsurf?"}]$x$::jsonb
 WHERE slug = 'windsurf' AND lang = 'de';

