UPDATE tools SET faq = $x$[{"a": "Windsurf s'appelle désormais Devin Desktop, un éditeur de code natif IA de Cognition qui a évolué à partir de Codeium/Windsurf. Sa capacité phare est un centre de commande d'agents offrant des agents de codage autonomes tels que Devin Local, Devin Cloud, Codex, Claude Agent, OpenCode et Cascade, avec une connaissance de votre base de code.", "q": "Qu'est-ce que Windsurf ?"}, {"a": "Devin Desktop (anciennement Windsurf) propose une formule gratuite avec un quota d'agent léger, un accès limité aux modèles, et des complétions Tab et modifications en ligne illimitées. Pro coûte 20 $ par mois pour plus de quota et un accès complet aux modèles.", "q": "Windsurf est-il gratuit ?"}, {"a": "Les deux sont de solides IDE IA et l'écart entre eux se réduit. Cursor propose davantage de fonctionnalités, une communauté plus large et plus d'options de modèles. La configuration multi-agents de Devin Desktop et sa formule gratuite sont des avantages. De nombreux développeurs essaient les deux ; le meilleur choix dépend souvent des préférences de flux de travail personnelles.", "q": "Windsurf est-il meilleur que Cursor ?"}, {"a": "Cascade est l'un des nombreux agents de codage sélectionnables disponibles dans Devin Desktop, aux côtés de Devin Local, Codex, Claude Agent et OpenCode. Il s'agissait de l'agent original de Windsurf et il peut toujours planifier et exécuter des modifications en plusieurs étapes à travers un projet.", "q": "Qu'est-ce que Cascade dans Windsurf ?"}]$x$::jsonb
 WHERE slug = 'windsurf' AND lang = 'fr';

