UPDATE tools SET faq = $x$[{"a": "O Windsurf agora se chama Devin Desktop, um editor de código nativo de IA da Cognition que evoluiu do Codeium/Windsurf. Sua principal funcionalidade é uma central de comando de agentes, oferecendo agentes de codificação autônomos como Devin Local, Devin Cloud, Codex, Claude Agent, OpenCode e Cascade, com conhecimento da sua base de código.", "q": "O que é o Windsurf?"}, {"a": "O Devin Desktop (antigo Windsurf) tem um plano gratuito com uma cota leve de agentes, acesso limitado a modelos e uso ilimitado de autocompletar com Tab e edições inline. O plano Pro custa US$ 20 por mês para mais cota e acesso total aos modelos.", "q": "O Windsurf é gratuito?"}, {"a": "Ambos são IDEs de IA sólidos, e a diferença entre eles está diminuindo. O Cursor tem mais recursos, uma comunidade maior e mais opções de modelos. A configuração multiagente e o plano gratuito do Devin Desktop são vantagens. Muitos desenvolvedores experimentam os dois; a melhor escolha geralmente depende da preferência pessoal de fluxo de trabalho.", "q": "O Windsurf é melhor que o Cursor?"}, {"a": "O Cascade é um dos vários agentes de codificação selecionáveis disponíveis no Devin Desktop, ao lado do Devin Local, Codex, Claude Agent e OpenCode. Foi o agente original do Windsurf e ainda é capaz de planejar e executar mudanças em várias etapas em um projeto.", "q": "O que é o Cascade no Windsurf?"}]$x$::jsonb
 WHERE slug = 'windsurf' AND lang = 'pt';

