UPDATE tools SET faq = $x$[{"q": "Was ist Replit?", "a": "Replit ist eine browserbasierte IDE und Cloud-Entwicklungsplattform. Du schreibst, führst aus und deployst Code vollständig im Browser — ohne lokale Installation. Sie unterstützt viele Programmiersprachen, und Replit Agent bietet KI-gestützte Coding-Unterstützung."}, {"q": "Ist Replit kostenlos?", "a": "Replits Preisseite führt derzeit keine kostenlose Kontostufe auf. Der Free Mode ist ein Nutzungsmodus innerhalb der kostenpflichtigen Core- und Pro-Pläne mit begrenzten Stunden und Projektanzahlen, die sich alle 5 Stunden zurücksetzen. Core beginnt bei 20 $/Monat bei monatlicher Abrechnung oder 18 $/Monat bei jährlicher Abrechnung."}, {"q": "Kann Replit Web-Apps deployen?", "a": "Ja. Replit verfügt über integrierte Deployments — du kannst Web-Apps, APIs und Datenbanken direkt aus deiner Replit-Umgebung heraus bereitstellen. Apps laufen auf Replits Infrastruktur unter einer .replit.app-Subdomain oder einer eigenen Domain."}, {"q": "Ist Replit gut für Anfänger geeignet?", "a": "Ja. Replit ist eine der zugänglicheren Plattformen für Anfänger — keine Einrichtung nötig, funktioniert in jedem Browser und unterstützt viele Programmiersprachen. Der KI-Agent hilft dabei, Code zu erklären und Fehler zu beheben. Viele Coding-Bootcamps und Schulen nutzen Replit aus diesem Grund."}]$x$::jsonb
