UPDATE tools SET faq = $x$[{"q": "Що таке Replit?", "a": "Replit — це браузерне IDE та хмарна платформа для розробки. Ви пишете, запускаєте та розгортаєте код повністю в браузері — без потреби в локальному встановленні. Платформа підтримує багато мов програмування, а Replit Agent надає допомогу у вигляді AI для кодування."}, {"q": "Чи є Replit безкоштовним?", "a": "Сторінка цін Replit наразі не містить безкоштовного тарифу. Free Mode це режим використання всередині платних планів Core та Pro з обмеженою кількістю годин і проєктів, що скидаються кожні 5 годин. Core починається від $20/місяць при щомісячній оплаті або $18/місяць при річній оплаті."}, {"q": "Чи може Replit розгортати веб-додатки?", "a": "Так. Replit має вбудовані засоби розгортання — ви можете розгортати веб-додатки, API та бази даних безпосередньо із середовища Replit. Додатки працюють на інфраструктурі Replit на піддомені .replit.app або власному домені."}, {"q": "Чи підходить Replit для початківців?", "a": "Так. Replit є однією з найдоступніших платформ для початківців — не потребує налаштування, працює в будь-якому браузері та підтримує багато мов програмування. AI-агент допомагає пояснювати код і виправляти помилки. Багато навчальних курсів з програмування та шкіл використовують Replit саме з цієї причини."}]$x$::jsonb
