UPDATE tools SET faq = $x$[{"q": "מהי Replit?", "a": "Replit היא סביבת פיתוח ענן (IDE) מבוססת דפדפן ופלטפורמת פיתוח בענן. אתם כותבים, מריצים ופורסים קוד כולו בדפדפן — ללא צורך בהתקנה מקומית. היא תומכת בשפות תכנות רבות, ו-Replit Agent מספק סיוע קידוד מבוסס AI."}, {"q": "האם Replit חינמית?", "a": "דף התמחור של Replit אינו כולל כעת רמת חשבון חינמית. Free Mode הוא מצב שימוש בתוך תוכניות התשלום Core ו-Pro, עם שעות ומספר פרויקטים מוגבלים המתאפסים כל 5 שעות. תוכנית Core מתחילה ב-$20 לחודש בחיוב חודשי, או $18 לחודש בחיוב שנתי."}, {"q": "האם Replit יכולה לפרוס אפליקציות ווב?", "a": "כן. ל-Replit יש יכולות פריסה מובנות — ניתן לפרוס אפליקציות ווב, ממשקי API ומסדי נתונים ישירות מסביבת Replit שלכם. האפליקציות פועלות על תשתית Replit בכתובת משנה של .replit.app או בדומיין מותאם אישית."}, {"q": "האם Replit טובה למתחילים?", "a": "כן. Replit היא אחת הפלטפורמות הנגישות ביותר למתחילים — אינה דורשת התקנה, פועלת בכל דפדפן, ותומכת בשפות תכנות רבות. סוכן ה-AI מסייע בהסבר קוד ותיקון שגיאות. בשל כך, מחנות קידוד (bootcamps) ובתי ספר רבים משתמשים ב-Replit."}]$x$::jsonb
