UPDATE tools SET faq = $x$[{"q": "Claude est-il meilleur que ChatGPT ?", "a": "Cela dépend de la tâche. Claude produit généralement une rédaction longue de qualité et peut traiter des documents très longs avec précision grâce à sa fenêtre de contexte d'1 million de tokens. ChatGPT propose davantage de fonctionnalités (génération d'images, voix, plugins) et un écosystème d'applications plus vaste. Les capacités en programmation varient selon le modèle et la tâche, il est donc utile de tester les deux pour votre propre flux de travail."}, {"q": "Lequel est gratuit — ChatGPT ou Claude ?", "a": "Les deux disposent de plans gratuits. Le plan Free de Claude donne accès aux modèles Sonnet et Haiku sans frais, avec des plafonds d'utilisation qui se réinitialisent de façon glissante. ChatGPT propose également un niveau gratuit avec ses propres limites d'utilisation. Le point d'entrée payant de Claude est le plan Pro à 20 $/mois facturé mensuellement, ou 17 $/mois si facturé annuellement."}, {"q": "Quelle IA est meilleure pour la programmation — ChatGPT ou Claude ?", "a": "Les deux sont d'excellents choix. Claude Opus 5.5 est conçu pour la programmation agentique complexe, et tous les modèles Claude actuels offrent une fenêtre de contexte d'1 million de tokens qui aide sur les grandes bases de code. ChatGPT avec l'interpréteur de code excelle dans l'analyse de données et l'exécution de code. Le meilleur choix dépendra de la tâche de programmation spécifique et du flux de travail."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'fr';

