UPDATE tools SET faq = $x$[{"q": "O Claude é melhor que o ChatGPT?", "a": "Depende da tarefa. O Claude geralmente produz textos longos de alta qualidade e consegue lidar com documentos muito longos com precisão, graças à sua janela de contexto de 1 milhão de tokens. O ChatGPT tem mais recursos (geração de imagens, voz, plugins) e um ecossistema de aplicativos maior. A capacidade de programação varia conforme o modelo e a tarefa, então vale a pena testar ambos para o seu fluxo de trabalho específico."}, {"q": "Qual é gratuito — ChatGPT ou Claude?", "a": "Ambos têm planos gratuitos. O plano Free do Claude dá acesso aos modelos Sonnet e Haiku sem custo, com limites de uso que são redefinidos de forma contínua. O ChatGPT também oferece um nível gratuito com seus próprios limites de uso. O ponto de entrada pago do Claude é o plano Pro, por US$ 20/mês cobrado mensalmente, ou US$ 17/mês se cobrado anualmente."}, {"q": "Qual IA é melhor para programação — ChatGPT ou Claude?", "a": "Ambas são boas opções. O Claude Opus 5.5 foi feito para programação complexa com agentes, e todos os modelos atuais do Claude oferecem uma janela de contexto de 1 milhão de tokens, o que ajuda em grandes bases de código. O ChatGPT com interpretador de código se destaca em análise de dados e execução de código. Qual é melhor vai depender da tarefa de programação específica e do fluxo de trabalho."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'pt';

