UPDATE tools SET faq = $x$[{"q": "Что такое Seedance?", "a": "Seedance — линейка моделей генерации видео с помощью ИИ от ByteDance. Текущая версия, Seedance 2.5, была запущена 31 июля 2026 года, сначала в Jimeng AI и Doubao Pro, с доступом через API BytePlus ModelArk, позже распространившись на Dreamina для подписчиков за пределами США."}, {"q": "Сколько стоит Seedance?", "a": "ByteDance не опубликовала прейскурантную цену на саму модель Seedance. Доступ предоставляется через кредитные подписки Dreamina, цены на которые указаны в местной валюте с тарифами от плана Basic до более дорогого плана Ultra с большим количеством кредитов; для использования Seedance 2.5 в Dreamina требуется платная подписка. Цены на API BytePlus ModelArk на момент обзора опубликованы не были."}, {"q": "Как получить доступ к Seedance?", "a": "Seedance доступна через собственные приложения ByteDance — Jimeng AI, Doubao, Dreamina и Dola, через API BytePlus ModelArk, а также через сторонних партнёров, таких как Higgsfield, Runway и DreamBench. По состоянию на конец октября 2026 года доступ к Dreamina ограничен подписчиками за пределами США, а BytePlus в США не работает."}]$x$::jsonb
