 WHERE slug = 'heygen' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is the difference between HeyGen and Synthesia?", "a": "HeyGen leads on video translation (lip-synced dubbing in 175+ languages) and natural-looking avatar quality. Synthesia leads on enterprise features, compliance, and LMS integration for corporate training. HeyGen targets marketing; Synthesia targets L&D teams."}, {"q": "Can HeyGen clone my voice?", "a": "Yes. HeyGen's in-house voice model, HeyGen Voice, can create an Instant Voice clone from under a minute of audio, or a higher-fidelity Professional Voice Clone from 30 minutes to 2 hours of audio (add-on from $29/month). Cloned voices are used in video translation, so your avatar can speak other languages in your own voice."}, {"q": "How much does HeyGen cost?", "a": "HeyGen's Creator plan is $29/month ($24/month billed annually) with 600 credits/month. Pro is $49/month with 1,000 credits/month, scaling up to 100,000 credits for $4,300/month. Business is $149/month plus $20 per additional seat, with 1,500 credits/month. Enterprise pricing is custom."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'en';

