UPDATE tools SET faq = $x$[{"q": "¿Cuál es la diferencia entre HeyGen y Synthesia?", "a": "HeyGen lidera en traducción de video (doblaje sincronizado labialmente en más de 175 idiomas) y calidad de avatar de aspecto natural. Synthesia lidera en funciones empresariales, cumplimiento normativo e integración con LMS para formación corporativa. HeyGen está orientado a marketing; Synthesia está orientado a equipos de L&D."}, {"q": "¿Puede HeyGen clonar mi voz?", "a": "Sí. El modelo de voz propio de HeyGen, HeyGen Voice, puede crear un clon de Voz Instantánea a partir de menos de un minuto de audio, o un Clon de Voz Profesional de mayor fidelidad a partir de 30 minutos a 2 horas de audio (complemento desde $29/mes). Las voces clonadas se utilizan en la traducción de video, de modo que tu avatar puede hablar otros idiomas con tu propia voz."}, {"q": "¿Cuánto cuesta HeyGen?", "a": "El plan Creator de HeyGen cuesta $29/mes ($24/mes con facturación anual) con 600 créditos/mes. Pro cuesta $49/mes con 1.000 créditos/mes, escalando hasta 100.000 créditos por $4.300/mes. Business cuesta $149/mes más $20 por asiento adicional, con 1.500 créditos/mes. El precio de Enterprise es personalizado."}]$x$::jsonb
