UPDATE tools SET faq = $x$[{"q": "Quelle est la différence entre HeyGen et Synthesia ?", "a": "HeyGen se distingue par la traduction vidéo (doublage synchronisé labialement en plus de 175 langues) et la qualité d'avatar à l'apparence naturelle. Synthesia se distingue par ses fonctionnalités d'entreprise, sa conformité et son intégration LMS pour la formation en entreprise. HeyGen cible le marketing ; Synthesia cible les équipes L&D (formation et développement)."}, {"q": "HeyGen peut-il cloner ma voix ?", "a": "Oui. Le modèle vocal maison de HeyGen, HeyGen Voice, peut créer un clonage Instant Voice à partir de moins d'une minute d'audio, ou un Professional Voice Clone de meilleure fidélité à partir de 30 minutes à 2 heures d'audio (option à partir de 29 $/mois). Les voix clonées sont utilisées dans la traduction vidéo, de sorte que votre avatar peut parler d'autres langues avec votre propre voix."}, {"q": "Combien coûte HeyGen ?", "a": "Le forfait Creator de HeyGen est à 29 $/mois (24 $/mois facturé annuellement) avec 600 crédits/mois. Pro est à 49 $/mois avec 1 000 crédits/mois, montant jusqu'à 100 000 crédits pour 4 300 $/mois. Business est à 149 $/mois plus 20 $ par siège supplémentaire, avec 1 500 crédits/mois. Le tarif Enterprise est personnalisé."}]$x$::jsonb
