UPDATE tools SET faq = $x$[{"q": "Is DeepSeek better than ChatGPT?", "a": "DeepSeek is a capable assistant for text reasoning, coding, and long-document work, offered through a web chat and a paid, metered API. It's a strong option if you want an inexpensive way to access capable AI models via API. ChatGPT has more built-in features (images, voice, plugins) and broader ecosystem support."}, {"q": "Is DeepSeek safe to use?", "a": "DeepSeek is developed by a Chinese AI lab. As a China-based service, it may raise data-residency or compliance questions for some organizations, so it's worth checking your organization's policies before sending sensitive data through the web chat or API."}, {"q": "Is DeepSeek free?", "a": "DeepSeek's API is a paid, metered service billed per million tokens, with separate peak and off-peak rates. For example, the deepseek-flash tier (currently served by DeepSeek-V4.1-Flash-1017) costs $0.15 per million input tokens on a cache miss during off-peak hours (as low as $0.003 on a cache hit) and $0.60 per million output tokens off-peak, roughly double during peak hours. New standalone Search and Fetch APIs cost $0.75 per 1,000 successful requests each, though calls made through DeepSeek Harness, Claude Code, or Codex are free until November 1, 2026 (00:00 Beijing time). The pricing page also mentions a 'granted balance' used before any topped-up balance, but does not explain how it is granted. Whether the web chat interface remains free could not be confirmed on a primary page at time of writing."}, {"q": "What is DeepSeek's reasoning model?", "a": "Reasoning is built into DeepSeek's current API as a default thinking mode, available in both deepseek-flash and deepseek-v4-pro, with selectable low, high, and max effort levels for different depths of reasoning."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'en';

