UPDATE tools SET faq = $x$[{"q": "Ist DeepSeek besser als ChatGPT?", "a": "DeepSeek ist ein leistungsfähiger Assistent für Textverständnis, Programmierung und die Arbeit mit langen Dokumenten, verfügbar über einen Web-Chat und eine kostenpflichtige, verbrauchsabhängige API. Es ist eine gute Option, wenn Sie kostengünstig über eine API auf leistungsfähige KI-Modelle zugreifen möchten. ChatGPT bietet mehr integrierte Funktionen (Bilder, Sprache, Plugins) und eine breitere Ökosystem-Unterstützung."}, {"q": "Ist DeepSeek sicher in der Nutzung?", "a": "DeepSeek wird von einem chinesischen KI-Labor entwickelt. Als in China ansässiger Dienst kann er bei manchen Organisationen Fragen zu Datenresidenz oder Compliance aufwerfen, daher lohnt es sich, die Richtlinien Ihrer Organisation zu prüfen, bevor Sie sensible Daten über den Web-Chat oder die API senden."}, {"q": "Ist DeepSeek kostenlos?", "a": "Die API von DeepSeek ist ein kostenpflichtiger, verbrauchsabhängiger Dienst, der pro Million Token abgerechnet wird, mit separaten Spitzen- und Nebenzeitpreisen. Zum Beispiel kostet die Stufe deepseek-flash (derzeit bereitgestellt von DeepSeek-V4.1-Flash-1017) 0,15 $ pro Million Eingabe-Token bei einem Cache-Miss in der Nebenzeit (nur 0,003 $ bei einem Cache-Hit) und 0,60 $ pro Million Ausgabe-Token in der Nebenzeit, zur Spitzenzeit etwa doppelt so viel. Die neuen eigenständigen Search- und Fetch-APIs kosten jeweils 0,75 $ pro 1.000 erfolgreiche Anfragen, wobei Aufrufe über DeepSeek Harness, Claude Code oder Codex bis zum 1. November 2026 (00:00 Uhr Pekinger Zeit) kostenlos sind. Die Preisseite erwähnt zudem ein „gewährtes Guthaben“, das vor einem aufgeladenen Guthaben verwendet wird, erklärt aber nicht, wie es gewährt wird. Ob die Web-Chat-Oberfläche weiterhin kostenlos bleibt, konnte zum Zeitpunkt der Erstellung auf keiner primären Seite bestätigt werden."}, {"q": "Was ist das Reasoning-Modell von DeepSeek?", "a": "Reasoning ist als standardmäßiger Denkmodus in die aktuelle API von DeepSeek integriert, verfügbar sowohl bei deepseek-flash als auch bei deepseek-v4-pro, mit wählbaren Aufwandsstufen niedrig, hoch und maximal für unterschiedliche Reasoning-Tiefen."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'de';

