UPDATE tools SET faq = $x$[{"q": "האם DeepSeek טוב יותר מ-ChatGPT?", "a": "DeepSeek הוא עוזר מוכשר לחשיבה טקסטואלית, קידוד, ועבודה עם מסמכים ארוכים, המוצע באמצעות צ'אט מבוסס אינטרנט ו-API בתשלום לפי מדידה. זוהי אפשרות טובה אם אתם רוצים דרך זולה לגשת למודלי AI מוכשרים באמצעות API. ל-ChatGPT יש יותר תכונות מובנות (תמונות, קול, תוספים) ותמיכה רחבה יותר במערכת האקולוגית."}, {"q": "האם בטוח להשתמש ב-DeepSeek?", "a": "DeepSeek פותח על ידי מעבדת AI סינית. כשירות המבוסס בסין, הוא עלול לעורר שאלות לגבי מיקום נתונים או ציות רגולטורי עבור ארגונים מסוימים, לכן כדאי לבדוק את המדיניות של הארגון שלכם לפני שליחת מידע רגיש דרך הצ'אט המבוסס אינטרנט או ה-API."}, {"q": "האם DeepSeek חינמי?", "a": "ה-API של DeepSeek הוא שירות בתשלום לפי מדידה המחויב לפי מיליון טוקנים, עם תעריפי שיא ושפל נפרדים. לדוגמה, רמת deepseek-flash (המוגשת כעת על ידי DeepSeek-V4.1-Flash-1017) עולה 0.15$ למיליון טוקני קלט ב-cache miss בשעות שפל (עד 0.003$ בלבד ב-cache hit) ו-0.60$ למיליון טוקני פלט בשפל, כפול בערך בשעות שיא. ה-APIs העצמאיים החדשים לחיפוש ואחזור עולים 0.75$ לכל 1,000 בקשות מוצלחות, אם כי קריאות שבוצעו דרך DeepSeek Harness, Claude Code, או Codex חינמיות עד 1 בנובמבר 2026 (00:00 שעון בייג'ינג). דף התמחור מזכיר גם 'יתרה מוענקת' שמשמשת לפני כל יתרה שהוטענה, אך אינו מסביר כיצד היא מוענקת. לא ניתן היה לאמת במקור ראשי בעת כתיבת שורות אלו האם ממשק הצ'אט המבוסס אינטרנט נותר חינמי."}, {"q": "מהו מודל ה-reasoning של DeepSeek?", "a": "יכולת חשיבה (reasoning) מובנית כעת ב-API הנוכחי של DeepSeek כמצב חשיבה ברירת מחדל, הזמין הן ב-deepseek-flash והן ב-deepseek-v4-pro, עם רמות מאמץ נבחרות - נמוכה, גבוהה, ומקסימלית - לעומק חשיבה שונה."}]$x$::jsonb
