UPDATE tools SET faq = $x$[{"q": "DeepSeek est-il meilleur que ChatGPT ?", "a": "DeepSeek est un assistant performant pour le raisonnement textuel, le code et le traitement de documents longs, proposé via un chat web et une API payante facturée à l'usage. C'est une option solide si vous voulez un moyen peu coûteux d'accéder à des modèles d'IA performants via API. ChatGPT offre plus de fonctionnalités intégrées (images, voix, plugins) et un écosystème plus large."}, {"q": "DeepSeek est-il sûr à utiliser ?", "a": "DeepSeek est développé par un laboratoire d'IA chinois. En tant que service basé en Chine, il peut soulever des questions de résidence des données ou de conformité pour certaines organisations ; il est donc utile de vérifier les politiques de votre organisation avant d'envoyer des données sensibles via le chat web ou l'API."}, {"q": "DeepSeek est-il gratuit ?", "a": "L'API de DeepSeek est un service payant facturé à l'usage par million de tokens, avec des tarifs distincts en heures de pointe et hors pointe. Par exemple, le niveau deepseek-flash (actuellement servi par DeepSeek-V4.1-Flash-1017) coûte 0,15 $ par million de tokens d'entrée en cas d'échec de cache hors pointe (aussi bas que 0,003 $ en cas de succès de cache) et 0,60 $ par million de tokens de sortie hors pointe, environ le double en heures de pointe. Les nouvelles API Search et Fetch autonomes coûtent chacune 0,75 $ pour 1 000 requêtes réussies, bien que les appels effectués via DeepSeek Harness, Claude Code ou Codex soient gratuits jusqu'au 1er novembre 2026 (0h00 heure de Pékin). La page de tarification mentionne également un « solde accordé » utilisé avant tout solde rechargé, sans expliquer comment il est accordé. On ne peut pas confirmer, à partir d'une page primaire au moment de la rédaction, si l'interface de chat web reste gratuite."}, {"q": "Quel est le modèle de raisonnement de DeepSeek ?", "a": "Le raisonnement est intégré à l'API actuelle de DeepSeek sous forme de mode de réflexion par défaut, disponible à la fois dans deepseek-flash et deepseek-v4-pro, avec des niveaux d'effort sélectionnables parmi faible, élevé et maximal pour différents degrés de raisonnement."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'fr';

