UPDATE tools SET faq = $x$[{"q": "¿Qué es Lovable?", "a": "Lovable (antes GPT Engineer) es un creador de aplicaciones con IA en el que describes lo que quieres y genera una aplicación web completa en React/TypeScript. A diferencia de las herramientas sin código, produce código real. Los desarrolladores pueden editar el código directamente o seguir conversando con la IA para hacer cambios."}, {"q": "¿Es gratis Lovable?", "a": "Lovable tiene un plan gratuito con 5 créditos de construcción por día (hasta unos 30 al mes), más 20 créditos de Cloud y 4 créditos de IA en la aplicación al mes. Los planes de pago empiezan en 25 $/mes (Pro) o 21 $/mes con facturación anual, y 50 $/mes (Business) o 42 $/mes con facturación anual, ambos para una base de 100 créditos que escala a niveles superiores. Se consumen créditos, no mensajes, al generar o modificar código."}, {"q": "¿Es Lovable mejor que Bubble para quienes no son desarrolladores?", "a": "Bubble es, en general, mejor para quienes no son desarrolladores y quieren construir sin escribir código. Lovable genera código real que, aunque impresionante, puede requerir conocimientos de desarrollo para depurar y mantener. Para fundadores sin perfil técnico, el editor visual de Bubble es más accesible."}, {"q": "¿Puede Lovable construir aplicaciones full-stack?", "a": "Sí. Lovable puede conectarse a Supabase para base de datos y autenticación, generando aplicaciones full-stack con un frontend en React y un backend en PostgreSQL. Es popular para construir prototipos de SaaS y MVP rápidamente."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'es';

