UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Lovable ?", "a": "Lovable (anciennement GPT Engineer) est un créateur d'applications IA où vous décrivez ce que vous voulez et il génère une application web React/TypeScript complète. Contrairement aux outils no-code, il produit du code réel. Les développeurs peuvent éditer le code directement ou continuer à dialoguer avec l'IA pour apporter des modifications."}, {"q": "Lovable est-il gratuit ?", "a": "Lovable propose un plan gratuit avec 5 crédits de build par jour (jusqu'à environ 30 par mois), plus 20 crédits Cloud et 4 crédits d'IA intégrée par mois. Les plans payants commencent à 25 $/mois (Pro) ou 21 $/mois facturé annuellement, et 50 $/mois (Business) ou 42 $/mois facturé annuellement, tous deux pour une base de 100 crédits évolutive vers des paliers supérieurs. Ce sont les crédits, et non les messages, qui sont consommés lors de la génération ou de la modification du code."}, {"q": "Lovable est-il meilleur que Bubble pour les non-développeurs ?", "a": "Bubble convient généralement mieux aux non-développeurs qui souhaitent construire sans écrire de code. Lovable génère du code réel qui, bien qu'impressionnant, peut nécessiter des connaissances de développeur pour le déboguer et le maintenir. Pour les fondateurs non techniques, l'éditeur visuel de Bubble est plus accessible."}, {"q": "Lovable peut-il créer des applications full-stack ?", "a": "Oui. Lovable peut se connecter à Supabase pour la base de données et l'authentification, générant des applications full-stack avec un frontend React et un backend PostgreSQL. Il est populaire pour créer rapidement des prototypes SaaS et des MVP."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'fr';

