UPDATE tools SET faq = $x$[{"q": "O que é o Lovable?", "a": "Lovable (anteriormente GPT Engineer) é um criador de apps com IA no qual você descreve o que deseja e ele gera uma aplicação web completa em React/TypeScript. Diferente das ferramentas no-code, ele produz código real. Desenvolvedores podem editar o código diretamente ou continuar conversando com a IA para fazer alterações."}, {"q": "O Lovable é gratuito?", "a": "O Lovable tem um plano gratuito com 5 créditos de build por dia (até cerca de 30 por mês), além de 20 créditos Cloud e 4 créditos de IA no aplicativo por mês. Os planos pagos começam em $25/mês (Pro) ou $21/mês cobrado anualmente, e $50/mês (Business) ou $42/mês cobrado anualmente, ambos com uma base de 100 créditos que escala para níveis superiores. Créditos, e não mensagens, são consumidos ao gerar ou modificar código."}, {"q": "O Lovable é melhor que o Bubble para quem não é desenvolvedor?", "a": "O Bubble geralmente é melhor para quem não é desenvolvedor e quer construir sem escrever código. O Lovable gera código real, o que, embora impressionante, pode exigir conhecimento de desenvolvedor para depurar e manter. Para fundadores não técnicos, o editor visual do Bubble é mais acessível."}, {"q": "O Lovable consegue construir apps full-stack?", "a": "Sim. O Lovable pode se conectar ao Supabase para banco de dados e autenticação, gerando aplicações full-stack com frontend em React e backend em PostgreSQL. É popular para construir protótipos de SaaS e MVPs rapidamente."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'pt';
